create extension if not exists pgcrypto;
create table if not exists public.loans(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,name text not null,original_amount numeric(14,2) not null check(original_amount>0),balance numeric(14,2) not null check(balance>=0),annual_rate numeric(7,3) not null default 0 check(annual_rate between 0 and 100),emi numeric(14,2) not null check(emi>0),due_day integer check(due_day between 1 and 31),status text not null default 'ACTIVE' check(status in ('ACTIVE','CLOSED')),created_at timestamptz default now(),updated_at timestamptz default now(),check(balance<=original_amount));
create table if not exists public.loan_payments(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,loan_id uuid not null references public.loans(id) on delete cascade,amount numeric(14,2) not null check(amount>0),principal numeric(14,2) not null default 0 check(principal>=0),interest numeric(14,2) not null default 0 check(interest>=0),payment_date date not null default current_date,note text,created_at timestamptz default now(),check(principal+interest<=amount));
create table if not exists public.income_entries(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,amount numeric(14,2) not null check(amount>0),category text not null default 'Income',entry_date date default current_date,note text,created_at timestamptz default now());
create table if not exists public.expense_entries(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,amount numeric(14,2) not null check(amount>0),category text not null default 'Expense',entry_date date default current_date,note text,created_at timestamptz default now());
create table if not exists public.financial_goals(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,name text not null,goal_type text not null check(goal_type in ('DEBT_FREE','EMERGENCY_FUND','SAVINGS','CUSTOM')),target_amount numeric(14,2) not null check(target_amount>0),current_amount numeric(14,2) not null default 0 check(current_amount>=0),target_date date,monthly_target numeric(14,2) not null default 0 check(monthly_target>=0),status text not null default 'ACTIVE' check(status in ('ACTIVE','COMPLETED','PAUSED')),note text,created_at timestamptz default now(),updated_at timestamptz default now(),check(current_amount<=target_amount));
alter table public.loans enable row level security; alter table public.loan_payments enable row level security; alter table public.income_entries enable row level security; alter table public.expense_entries enable row level security; alter table public.financial_goals enable row level security;
drop policy if exists loans_all_own on public.loans; create policy loans_all_own on public.loans for all using(auth.uid()=user_id) with check(auth.uid()=user_id);
drop policy if exists payments_all_own on public.loan_payments; create policy payments_all_own on public.loan_payments for all using(auth.uid()=user_id) with check(auth.uid()=user_id);
drop policy if exists income_all_own on public.income_entries; create policy income_all_own on public.income_entries for all using(auth.uid()=user_id) with check(auth.uid()=user_id);
drop policy if exists expense_all_own on public.expense_entries; create policy expense_all_own on public.expense_entries for all using(auth.uid()=user_id) with check(auth.uid()=user_id);
drop policy if exists goals_all_own on public.financial_goals; create policy goals_all_own on public.financial_goals for all using(auth.uid()=user_id) with check(auth.uid()=user_id);
